#!/usr/bin/env node
// Embeds llmdocs/*.md into src/llmdocs.generated.ts.
//
// tsc only compiles TypeScript, so the Markdown has to become TypeScript to
// survive into dist/ and be readable from a globally installed package. The
// generated file is committed for the same reason Go projects commit theirs:
// the build needs it to exist. `yarn build` regenerates it first, and CI fails
// if the committed copy is stale.
const fs = require('fs')
const path = require('path')

const docsDir = path.join(__dirname, '..', 'llmdocs')
const outPath = path.join(__dirname, '..', 'src', 'llmdocs.generated.ts')

const files = fs
  .readdirSync(docsDir)
  .filter((name) => name.endsWith('.md'))
  .sort()

const sections = files.map((name) => {
  const body = fs.readFileSync(path.join(docsDir, name), 'utf8').replace(/\n+$/, '')
  const title = (body.split('\n').find((line) => line.startsWith('# ')) || '').replace(/^#\s*/, '')
  return { file: name, title, body }
})

const out = `// Code generated by scripts/build-llmdocs.js. DO NOT EDIT.
// Source of truth: llmdocs/*.md — edit those and run \`yarn build-llmdocs\`.

export interface LlmSection {
  file: string
  title: string
  body: string
}

export const sections: LlmSection[] = ${JSON.stringify(sections, null, 2)}
`

fs.writeFileSync(outPath, out)
process.stderr.write(`wrote ${path.relative(process.cwd(), outPath)} (${files.length} chapters, ${out.length} bytes)\n`)
